import java.io.*;
import java.util.*;

public class AltSolution {
    static Scanner scanner;
    static PrintWriter printer;
    static long MODULUS = 1_000_000_000L + 7;

    public static void main(String[] args) throws Exception {
        StringBuilder inputSample = new StringBuilder();
        if (inputSample.length() == 0) {
            scanner = new Scanner(System.in);
        } else {
            scanner = new Scanner(new StringReader(inputSample.toString()));
        }
        printer = new PrintWriter(new OutputStreamWriter(System.out));
        initialize();
        process();
        printer.flush();
    }

    private static void initialize() {
        // No data initialization required
    }

    private static void process() throws IOException {
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        int l = scanner.nextInt() - 1;
        int r = scanner.nextInt() - 1;
        int segmentSize = r - l + 1;
        int minS = segmentSize;

        for (char firstLetter = 'a'; firstLetter <= 'z'; firstLetter++)
            for (char secondLetter = 'a'; secondLetter <= 'z'; secondLetter++)
                for (char thirdLetter = 'a'; thirdLetter <= 'z'; thirdLetter++)
                    minS = Math.min(minS, evaluateOverlap(a, b, l, r, new char[]{firstLetter, secondLetter, thirdLetter}));

        printer.println(minS);
    }

    private static int evaluateOverlap(int a, int b, int idxStart, int idxEnd, char[] patternChars) {
        char[] combined = new char[3 * (a + b)];
        for (int index = 0; index < 3; index++) {
            System.arraycopy(extractUniqueChars(combined, index * (a + b), a), 0,
                             combined, index * (a + b), a);
            Arrays.fill(combined, index * (a + b) + a, (index + 1) * (a + b), patternChars[index]);
        }

        int offset = idxStart % (a + b);
        int length = idxEnd - idxStart + 1;
        combined = Arrays.copyOfRange(combined, offset, combined.length);
        combined = Arrays.copyOf(combined, Math.min(combined.length, length));

        boolean[] seenChars = new boolean[26];
        for (char c : combined) {
            seenChars[c - 'a'] = true;
        }

        int countTypes = 0;
        for (boolean seen : seenChars) {
            if (seen) countTypes++;
        }
        return countTypes;
    }

    private static char[] extractUniqueChars(char[] array, int baseIndex, int totalChars) {
        boolean[] usedLetters = new boolean[26];
        for (int i = baseIndex - 1; i >= 0 && i >= baseIndex - totalChars; i--) {
            usedLetters[array[i] - 'a'] = true;
        }
        char[] res = new char[totalChars];
        char chPointer = 'a';
        int i = 0;
        while (i < totalChars) {
            while (usedLetters[chPointer - 'a']) chPointer++;
            res[i++] = chPointer++;
        }
        return res;
    }
}
